export const MENU_CSS = "\n:root{--green:#285343;--red:#984735;--ink:#26352d;--muted:#627166;--cream:#ffffff;--line:#e1e5da;color:var(--ink);background:var(--cream);font-family:system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}*{box-sizing:border-box}body{margin:0;min-width:320px}button,input{font:inherit}button,a,input{touch-action:manipulation}button{cursor:pointer}a{color:inherit}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid var(--red);outline-offset:4px}.skip{position:absolute;left:16px;top:-80px;background:white;padding:12px;z-index:10}.skip:focus{top:12px}.draft-strip{background:#fff0d5;border-bottom:1px solid #eadbbd;font-size:12px;text-align:center;padding:12px 20px;line-height:1.6;color:#68491b}.shell{max-width:1000px;margin:auto;padding:0 28px}.masthead{display:flex;justify-content:space-between;gap:20px;align-items:center;padding-top:22px}.powered{font-size:11px;letter-spacing:.06em;text-decoration:none;color:var(--muted)}.edition{font-size:10px;letter-spacing:.18em;color:var(--muted)}.hero{position:relative;text-align:center;padding:46px 0 38px;border-bottom:1px solid var(--line)}.hero:before{content:'';display:block;width:34px;height:3px;margin:0 auto 20px;background:var(--green);border-radius:99px}.eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.22em;color:var(--muted)}h1{font-family:Georgia,serif;font-weight:400;font-style:italic;font-size:clamp(54px,11vw,82px);letter-spacing:-.055em;color:var(--red);margin:6px 0 0}.tagline{font-family:Georgia,serif;font-style:italic;font-size:20px;color:var(--green);margin:10px 0 26px}.hero-copy{font-size:13px;color:var(--muted);line-height:1.7;max-width:420px;margin:0 auto}.menu-header{display:flex;gap:20px;justify-content:space-between;align-items:center;padding:30px 0 18px}.menu-header h2{font-family:Georgia,serif;font-size:28px;font-weight:400;margin:0}.count{font-size:12px;color:var(--muted)}.search{position:relative;display:block;margin-bottom:16px}.search svg{position:absolute;top:17px;left:16px;color:var(--green)}.search input{border:1px solid #cdd7cc;border-radius:12px;padding:15px 16px 15px 46px;background:#fff;width:100%;color:var(--ink);font-size:15px}.search input::placeholder{color:#788277}.navigation{position:sticky;top:0;background:var(--cream);padding:8px 0 14px;z-index:2;border-bottom:1px solid var(--line)}.tabs{display:flex;overflow:auto;gap:8px;padding:3px 3px 5px;scrollbar-width:thin}.tab{white-space:nowrap;border:1px solid #d4ddcf;background:transparent;padding:11px 15px;border-radius:99px;color:var(--green);font-size:12px;min-height:42px}.tab.selected{background:var(--green);border-color:var(--green);color:white}.charges{font-size:12px;color:#6c5942;background:#ffffff;border:1px solid var(--line);border-radius:9px;padding:13px 16px;line-height:1.7;margin-top:20px}.charges strong{font-weight:600}.menu{display:grid;grid-template-columns:1fr 1fr;column-gap:48px;align-items:start}.menu-category{padding:24px 0 8px;min-width:0}.category-heading{display:flex;align-items:center;gap:14px;border-bottom:2px solid var(--green);padding-bottom:12px}.category-heading h2{font-family:Georgia,serif;color:var(--green);font-weight:400;font-size:25px;margin:0;flex:1}.category-heading>span{font-size:11px;color:var(--muted)}ul{list-style:none;padding:0;margin:0}.item{display:flex;justify-content:space-between;gap:18px;padding:18px 0;border-bottom:1px solid var(--line);break-inside:avoid}.item>div{min-width:0}.item h3{font-size:14px;line-height:1.5;font-weight:600;margin:0}.item p{font-size:12px;line-height:1.7;color:var(--muted);margin:7px 0 0}.price{font-size:14px;white-space:nowrap;font-variant-numeric:tabular-nums;color:var(--red);padding-top:3px;font-weight:650}.price small{display:block;text-align:right;font-size:9px;font-weight:400;letter-spacing:.1em;margin-top:4px;color:var(--muted)}.review-price{font-size:10px;display:inline-block;margin-top:7px;color:#795217;background:#fff0d5;padding:3px 7px;border-radius:4px}.empty{padding:40px 0;text-align:center;color:var(--muted)}.review{margin:44px 0 24px;border:1px solid #d9d5c8;padding:20px;border-radius:12px;background:#ffffff}.review summary{cursor:pointer;font-size:14px;font-weight:650;color:var(--red)}.review-intro{font-size:12px;line-height:1.7;color:var(--muted)}.review li{padding:16px 0;border-top:1px solid var(--line)}.review li strong{font-size:13px}.review li p{font-size:12px;line-height:1.75;color:var(--muted);margin-bottom:0}.downloads{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0 4px}.downloads button{min-height:44px;border:1px solid var(--green);border-radius:8px;padding:10px 14px;background:white;color:var(--green);font-size:12px}.footer{text-align:center;padding:26px 10px 36px;border-top:1px solid var(--line);margin-top:32px}.footer .thanks{font-family:Georgia,serif;font-style:italic;color:var(--green);font-size:25px}.footer p{font-size:10px;line-height:1.8;color:var(--muted)}[hidden]{display:none!important}@media(max-width:700px){.shell{padding:0 20px}.hero{padding-top:32px}.masthead{padding-top:18px}.menu{grid-template-columns:1fr}.menu-category{padding-top:28px}.menu-header{padding-top:25px}.edition{font-size:9px}.hero-copy{max-width:300px}.category-heading h2{font-size:24px}.item{padding:17px 0}.item h3{font-size:14px}}@media print{body{background:white}.draft-strip{background:white}.navigation,.search,.downloads,.powered{display:none}.menu{display:block;columns:2;column-gap:30px}.menu-category{break-inside:avoid}.review{break-before:page}.review>ul{display:block}.hero{padding:18px 0}.hero h1{font-size:46px}.menu-category h2{font-size:20px}.item{padding:10px 0}.shell{padding:0}}\n.hero:before{display:none}.hero{padding:28px 0 32px}.occasion-brand{margin:12px 0 18px}.occasion-logo{display:block;width:min(230px,70vw);height:auto;margin:0 auto}.hero .hero-copy{margin-top:14px}@media(max-width:700px){.hero{padding:22px 0 28px}.occasion-logo{width:200px}}@media print{.occasion-logo{width:160px}}\n\n/* Integrated restaurant template */\n.hero h1{margin:12px 0 18px}.hero .occasion-logo{width:min(210px,65vw);height:auto;margin:auto;display:block}.hero{padding:24px 0 30px}.draft-strip{display:flex;flex-wrap:wrap;justify-content:center;gap:8px 16px}.draft-strip a{font-weight:600}.menu{grid-template-columns:repeat(2,minmax(0,1fr))}.item-copy{flex:1;min-width:0}.food-photo{width:74px;height:74px;object-fit:cover;border-radius:10px;flex-shrink:0}.contact-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin:20px 0 0}.contact-actions a{border:1px solid var(--line);border-radius:99px;padding:10px 14px;font-size:12px;text-decoration:none;color:var(--green)}.address{font-size:12px;color:var(--muted);line-height:1.7}.search>span{position:absolute;left:16px;top:7px;font-size:30px;color:var(--green)}.back-top{display:block;margin:30px auto 0;border:1px solid var(--line);border-radius:99px;background:#fff;color:var(--green);font-size:12px;min-height:44px;padding:10px 18px}.footer>a{font-size:10px;color:var(--muted);text-decoration:none}.charges p{margin:6px 0 0}.item h3{overflow-wrap:anywhere}@media(max-width:700px){.menu{grid-template-columns:minmax(0,1fr)}.hero .occasion-logo{width:180px}.food-photo{width:60px;height:60px}.item{gap:12px}.draft-strip{font-size:11px}.draft-strip>span{flex-basis:100%}.charges{font-size:11px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n\n/* Social connections and sharing */\n.contact-actions .contact-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid #d8e2da;border-radius:12px;padding:12px 18px;min-height:46px;font-size:13px;font-weight:550;background:#fff;color:var(--green);text-decoration:none}.contact-actions .primary{background:var(--green);border-color:var(--green);color:#fff}.contact-button:hover{border-color:var(--green)}.share-status{min-height:20px;font-size:12px;color:var(--green);margin:12px 0 0}.share-fallback{display:grid;gap:8px;font-size:12px;max-width:430px;margin:12px auto}.share-fallback input{width:100%;padding:12px;border:1px solid var(--line);border-radius:8px;font-size:12px}.connect-panel{margin:42px 0 12px;padding:30px;background:#f5f8f5;border:1px solid #e0e7df;border-radius:20px}.connect-heading h2{font:400 29px Georgia,serif;margin:10px 0;color:var(--green)}.connect-heading>p:last-child{font-size:13px;color:var(--muted);line-height:1.7}.social-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:24px 0}.social-card{display:flex;align-items:center;gap:14px;min-width:0;padding:18px;background:#fff;border:1px solid #dce4da;border-radius:13px;text-decoration:none;transition:box-shadow .15s}.social-card:hover{box-shadow:0 5px 20px #2853430d;border-color:#9cb5a4}.social-icon{width:44px;height:44px;display:grid;place-items:center;background:#edf4ed;color:var(--green);border-radius:12px;flex-shrink:0}.social-card strong{display:block;font-size:14px}.social-card small{display:block;color:var(--muted);font-size:11px;margin-top:6px}.social-arrow{margin-left:auto;color:var(--green)}.menu-qr{border-top:1px solid #dce4da;padding-top:18px;margin-top:18px}.menu-qr summary{font-size:13px;color:var(--green);cursor:pointer;min-height:32px;padding:5px 0}.qr-content{display:flex;align-items:center;gap:24px;padding-top:20px}.qr-content img{background:#fff;max-width:100%;height:auto;border-radius:12px}.qr-content h3{font:400 23px Georgia,serif;color:var(--green);margin:0}.qr-content p,.qr-content a{font-size:12px;line-height:1.8;color:var(--muted)}@media(max-width:600px){.connect-panel{padding:22px 18px}.social-grid{grid-template-columns:1fr}.social-card{padding:15px}.qr-content{flex-direction:column;align-items:flex-start}.contact-actions .contact-button{padding:12px 14px;font-size:12px}.connect-heading h2{font-size:26px}}@media print{.contact-actions,.share-status,.share-fallback,.connect-panel{display:none}}\n";
export const MENU_SCRIPT = "const search = document.getElementById(\"search\");\nconst tabs = [...document.querySelectorAll(\".tab\")];\nconst groups = [...document.querySelectorAll(\".menu-category\")];\nlet chosen = \"all\";\nfunction filter() {\n  const query = search.value.trim().toLocaleLowerCase();\n  let count = 0;\n  for (const group of groups) {\n    let visible = 0;\n    for (const row of group.querySelectorAll(\".item\")) {\n      row.hidden = !((chosen === \"all\" || group.dataset.category === chosen) && row.dataset.search.includes(query));\n      if (!row.hidden) visible++;\n    }\n    group.hidden = visible === 0;\n    count += visible;\n  }\n  document.getElementById(\"count\").textContent = `${count} ${count === 1 ? \"item\" : \"items\"}`;\n  document.querySelector(\".empty\").hidden = count !== 0;\n  for (const tab of tabs) {\n    const active = tab.dataset.category === chosen;\n    tab.classList.toggle(\"selected\", active);\n    tab.setAttribute(\"aria-pressed\", String(active));\n  }\n}\nfor (const tab of tabs) tab.addEventListener(\"click\", () => { chosen = tab.dataset.category; filter(); });\nsearch.addEventListener(\"input\", () => { chosen = \"all\"; filter(); });\ndocument.getElementById(\"back-top\").addEventListener(\"click\", () => document.getElementById(\"menu\").scrollIntoView({behavior:window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches?\"instant\":\"smooth\"}));\ndocument.getElementById('share-menu')?.addEventListener('click',async()=>{\n  const url='https://menu.admakidigital.com/r/occasion',status=document.getElementById('share-status');\n  status.textContent='';\n  if(navigator.share){try{await navigator.share({title:'Occasion Menu',url});return;}catch(error){if(error.name==='AbortError')return;}}\n  try{await navigator.clipboard.writeText(url);status.textContent='Menu link copied. Ready to share.';}\n  catch{const fallback=document.getElementById('share-fallback');fallback.hidden=false;const input=fallback.querySelector('input');input.focus();input.select();status.textContent='Copy the menu link below to share it.';}\n});\n";
export const ADMIN_SCRIPT = "// Adds Occasion links to the existing dashboard without changing its menu editor.\nconst occasionId = \"895adc6a-cc13-5695-ad79-26d60c57c6d0\";\nfunction installOccasionLinks() {\n  if (/^#\\/r\\/occasion\\/?(?:\\?|$)/.test(location.hash)) {\n    location.replace(\"/r/occasion\");\n    return;\n  }\n  if (!/^#\\/(platform|admin)(\\/|$|\\?)/.test(location.hash)) {\n    document.querySelectorAll(\"[data-occasion-preview]\").forEach(link=>link.remove());\n    return;\n  }\n  const dashboard = document.querySelector(\".dashboard\");\n  if (!dashboard) return;\n  for (const row of dashboard.querySelectorAll(\".restaurant-row\")) {\n    if (![...row.querySelectorAll(\"a\")].some(a => a.getAttribute(\"href\")?.includes(`/admin/${occasionId}`))) continue;\n    addLink(row);\n  }\n  const namedRestaurant = dashboard.querySelector(\".sidebar-footer strong\")?.textContent?.trim();\n  const explicitRestaurant=location.hash.match(/^#\\/admin\\/([a-zA-Z0-9-]+)/)?.[1];\n  const isOccasion=explicitRestaurant?explicitRestaurant===occasionId:namedRestaurant === \"Occasion\";\n  if (isOccasion) {\n    const actions = dashboard.querySelector(\".dash-header-actions\");\n    if (actions) addLink(actions);\n  } else {\n    dashboard.querySelectorAll(\".dash-header-actions [data-occasion-preview]\").forEach(link=>link.remove());\n  }\n}\nfunction addLink(parent) {\n  if (parent.querySelector(\"[data-occasion-preview]\")) return;\n  const link = document.createElement(\"a\");\n  link.href = \"/preview/occasion\";\n  link.className = \"tiny-button\";\n  link.dataset.occasionPreview = \"true\";\n  link.textContent = \"Preview design\";\n  link.target = \"_blank\";\n  link.rel = \"noopener\";\n  parent.append(link);\n}\nfunction start() {\n  installOccasionLinks();\n  new MutationObserver(installOccasionLinks).observe(document.body,{subtree:true,childList:true});\n  window.addEventListener(\"hashchange\",installOccasionLinks);\n}\nif(document.readyState === \"loading\") document.addEventListener(\"DOMContentLoaded\",start,{once:true});\nelse start();\n";
